const request = $('INT | Governed AI Adapter').item.json ?? {};
const action = String(request.ai_action ?? '').trim();
const body = request.body && typeof request.body === 'object' && !Array.isArray(request.body) ? request.body : {};
const suppliedIntent = body.structured_intent && typeof body.structured_intent === 'object' && !Array.isArray(body.structured_intent);
const question = typeof body.question === 'string' ? body.question.trim() : '';
const result = request.agent_result && typeof request.agent_result === 'object' ? request.agent_result : null;
const policy = {
  provider_key: String($json.provider_key ?? ''),
  intent_enabled: $json.intent_enabled === true,
  summary_enabled: $json.summary_enabled === true,
  intent_model: String($json.intent_model ?? ''),
  summary_model: String($json.summary_model ?? ''),
  intent_temperature: Number($json.intent_temperature ?? 0),
  summary_temperature: Number($json.summary_temperature ?? 0.1),
  max_question_chars: Number($json.max_question_chars ?? 1000),
  max_summary_input_chars: Number($json.max_summary_input_chars ?? 20000),
};
return {
  ...request,
  ai_action: action,
  ai_policy: policy,
  ai_intent_should_run: action === 'intent' && policy.intent_enabled && !suppliedIntent &&
    !request.__revint_security_error && question.length > 0 && question.length <= policy.max_question_chars,
  ai_summary_should_run: action === 'summary' && policy.summary_enabled &&
    result?.status === 'approved' && request.management_summary_input &&
    JSON.stringify(request.management_summary_input).length <= policy.max_summary_input_chars,
};

const base = $('CTX | Attach AI Policy').item.json;
const parsed = $json.output && typeof $json.output === 'object' ? $json.output : null;
if (!parsed) {
  return {...base, ai_adapter:{action:'intent',status:'invalid_output',provider:base.ai_policy?.provider_key ?? null}};
}
return {
  ...base,
  body: {...(base.body ?? {}), structured_intent: parsed},
  ai_adapter:{
    action:'intent',status:'applied',provider:base.ai_policy.provider_key,
    model:base.ai_policy.intent_model, applied_at:new Date().toISOString()
  }
};

return {
  ...$json,
  ai_adapter:{
    action:'intent',
    status:$json.body?.structured_intent ? 'structured_intent_preserved' : 'disabled_or_ineligible',
    provider:$json.ai_policy?.provider_key ?? null,
    model:null,
    applied_at:new Date().toISOString()
  }
};

const base = $('CTX | Attach AI Policy').item.json;
const parsed = $json.output && typeof $json.output === 'object' ? $json.output : null;
return {
  ...base,
  management_summary: parsed,
  ai_adapter:{
    action:'summary',
    status:parsed ? 'applied' : 'invalid_output',
    provider:base.ai_policy?.provider_key ?? null,
    model:base.ai_policy?.summary_model ?? null,
    applied_at:new Date().toISOString()
  }
};

return {
  ...$json,
  management_summary:null,
  ai_adapter:{
    action:'summary',status:'disabled_or_ineligible',
    provider:$json.ai_policy?.provider_key ?? null,model:null,
    applied_at:new Date().toISOString()
  }
};
